class TestHyperparameterTuning:
    """Test hyperparameter tuning functionality."""

    def test_optuna_study_creation(self, sample_dataframe, mock_optuna):
        """Test that Optuna study is created correctly."""
        features, target = tp.split_features_target(
            sample_dataframe, 'performance_score'
        )
        
        study = tp.create_optuna_study(
            direction='minimize',
            n_trials=10,
            timeout_minutes=30
        )
        
        mock_optuna.create_study.assert_called_once()
        assert study is not None

    def test_objective_function(self, sample_dataframe):
        """Test the objective function for Optuna optimization."""
        features, target = tp.split_features_target(
            sample_dataframe, 'performance_score'
        )
        
        def objective(trial):
            params = {
                'n_estimators': trial.suggest_int('n_estimators', 10, 100),
                'learning_rate': trial.suggest_float('learning_rate', 0.01, 0.3),
                'max_depth': trial.suggest_int('max_depth', 2, 10)
            }
            model = tp.train_model(
                features, target,
                model_type='gradient_boosting',
                hyperparameters=params
            )
            return mean_squared_error(target, model.predict(features))
        
        study = optuna.create_study(direction='minimize')
        study.optimize(objective, n_trials=3)
        
        assert study.best_params is not None
        assert 'n_estimators' in study.best_params
        assert 'learning_rate' in study.best_params

    def test_time_series_cv(self, sample_dataframe):
        """Test time-series cross-validation."""
        features, target = tp.split_features_target(
            sample_dataframe, 'performance_score'
        )
        
        tscv = TimeSeriesSplit(n_splits=5)
        model = GradientBoostingRegressor(n_estimators=50)
        
        scores = cross_val_score(model, features, target, cv=tscv)
        assert len(scores) == 5
        assert all(score > -1 for score in scores)  # R² scores should be > -1

    def test_hyperparameter_optimization(self, sample_dataframe, mock_optuna):
        """Test full hyperparameter optimization flow."""
        features, target = tp.split_features_target(
            sample_dataframe, 'performance_score'
        )
        
        best_params = tp.optimize_hyperparameters(
            features, target,
            model_type='gradient_boosting',
            n_trials=5,
            timeout_minutes=10
        )
        
        assert isinstance(best_params, dict)
        assert 'n_estimators' in best_params
        assert 'learning_rate' in best_params


